from PySide6.QtWidgets import QComboBox, QLabel, QListWidget, QPushButton, QTextEdit, QVBoxLayout, QWidget
from core.multi_url_parser import extract_video_urls

class MultipleVideoPage(QWidget):
    def __init__(self, submit):
        super().__init__(); self.submit = submit; self.items = []; layout = QVBoxLayout(self); title = QLabel("Multiple Videos"); title.setObjectName("PageTitle"); layout.addWidget(title); note = QLabel("Paste arbitrary text. Playlist links are ignored and each video becomes an independent task."); note.setObjectName("Muted"); layout.addWidget(note); self.text = QTextEdit(); self.text.setPlaceholderText("Notes, titles, and YouTube URLs..."); layout.addWidget(self.text); self.quality = QComboBox(); self.quality.addItems(["240p SD (MP4)","360p SD (MP4)","480p SD (MP4)","720p HD (MP4)","1080p Full HD (MP4)","2K Quad HD (1440p MP4)","4K Ultra HD (2160p MP4)","MP3 Audio (320 kbps)"]); row = QHBoxLayout(); extract = QPushButton("Extract URLs"); extract.clicked.connect(self.extract); row.addWidget(extract); row.addWidget(self.quality); layout.addLayout(row); self.summary = QLabel("No URLs detected"); self.summary.setObjectName("Muted"); layout.addWidget(self.summary); self.list = QListWidget(); layout.addWidget(self.list, 1); download = QPushButton("Download Selected"); download.setObjectName("Primary"); download.clicked.connect(lambda: self.submit(self.items, self.quality.currentText())); layout.addWidget(download)
    def extract(self):
        result = extract_video_urls(self.text.toPlainText()); self.items = result.urls; self.list.clear(); self.list.addItems([f"{index:02d}  {url}" for index, url in enumerate(self.items, 1)]); self.summary.setText(f"{len(result.urls)} detected  |  {result.duplicates_removed} duplicates removed  |  {result.playlists_ignored} playlist URLs ignored")
